settings.custom_css:
/* =========================================================
   RAMIS PREMIUM CART HERO
   Container: f7685c5

   Primary : #006660
   Accent  : #FFCE3A
========================================================= */

selector {

    --green-dark: #003f3c;
    --green: #006660;
    --gold: #FFCE3A;

    position: relative;

    overflow: hidden;

    padding: 55px 6% !important;

    background:
        radial-gradient(
            circle at 88% 15%,
            rgba(255,206,58,0.12),
            transparent 29%
        ),
        radial-gradient(
            circle at 8% 85%,
            rgba(0,180,165,0.17),
            transparent 34%
        ),
        linear-gradient(
            135deg,
            #003f3c 0%,
            #006660 52%,
            #00332f 100%
        ) !important;

    border-radius:
        0 0 30px 30px;

    box-shadow:
        0 20px 60px rgba(0,63,60,0.18);

    isolation: isolate;
}


/* =========================================================
   BACKGROUND GLOW
========================================================= */

selector::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    top: -270px;
    right: -170px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(255,206,58,0.14),
            rgba(255,206,58,0.035) 45%,
            transparent 70%
        );

    filter: blur(10px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   SECOND GLOW
========================================================= */

selector::after {

    content: "";

    position: absolute;

    width: 350px;
    height: 350px;

    left: -180px;
    bottom: -240px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(0,190,175,0.20),
            transparent 70%
        );

    filter: blur(20px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   TEXT AREA
========================================================= */

selector .elementor-element-443b89b {

    position: relative;

    z-index: 3;

    padding: 15px 10px;
}


/* =========================================================
   TITLE
========================================================= */

selector .elementor-element-1ca883a {

    position: relative;

    margin-bottom: 22px !important;
}


selector .elementor-element-1ca883a p {

    margin: 0 !important;

    color: #ffffff !important;

    font-size:
        clamp(32px, 4vw, 46px) !important;

    font-weight: 900 !important;

    line-height: 1.4 !important;

    letter-spacing: -1px;

    text-shadow:
        0 8px 28px rgba(0,0,0,0.18);
}


/* =========================================================
   GOLD TITLE LINE
========================================================= */

selector .elementor-element-1ca883a::after {

    content: "";

    display: block;

    width: 55px;
    height: 4px;

    margin-top: 14px;

    background:
        #FFCE3A !important;

    border-radius: 20px;

    box-shadow:
        0 0 18px rgba(255,206,58,0.35);

    transition:
        width .35s ease;
}


selector .elementor-element-443b89b:hover
.elementor-element-1ca883a::after {

    width: 82px;
}


/* =========================================================
   DESCRIPTION
========================================================= */

selector .elementor-element-b49ccc2 {

    position: relative;

    z-index: 2;
}


selector .elementor-element-b49ccc2 p {

    max-width: 610px;

    margin: 0 !important;

    color:
        rgba(255,255,255,0.74) !important;

    font-size: 15px !important;

    line-height: 2.15 !important;

    transition:
        color .3s ease;
}


selector .elementor-element-443b89b:hover
.elementor-element-b49ccc2 p {

    color:
        rgba(255,255,255,0.88) !important;
}


/* =========================================================
   IMAGE AREA
========================================================= */

selector .elementor-element-4e8c012 {

    position: relative;

    z-index: 3;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 10px;
}


/* =========================================================
   IMAGE FRAME
========================================================= */

selector .elementor-element-6182d5c {

    position: relative;

    width: 100%;

    max-width: 470px;

    transform:
        rotate(2deg);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1);
}


/* =========================================================
   GOLD FRAME
========================================================= */

selector .elementor-element-6182d5c::before {

    content: "";

    position: absolute;

    inset: -10px;

    border-radius: 25px;

    border:
        1px solid rgba(255,206,58,0.30);

    background:
        linear-gradient(
            135deg,
            rgba(255,206,58,0.12),
            transparent 45%,
            rgba(255,255,255,0.04)
        );

    z-index: -1;

    transition:
        all .45s ease;
}


/* =========================================================
   IMAGE
========================================================= */

selector .elementor-element-6182d5c img {

    display: block;

    width: 100%;

    aspect-ratio: 3 / 2;

    object-fit: cover;

    border-radius: 20px;

    border:
        1px solid rgba(255,255,255,0.15);

    box-shadow:
        0 25px 55px rgba(0,0,0,0.28);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1),
        box-shadow .5s ease;
}


/* =========================================================
   IMAGE HOVER
========================================================= */

selector .elementor-element-4e8c012:hover
.elementor-element-6182d5c {

    transform:
        rotate(0deg)
        translateY(-7px);
}


selector .elementor-element-4e8c012:hover
.elementor-element-6182d5c::before {

    inset: -15px;

    border-color:
        rgba(255,206,58,0.55);

    box-shadow:
        0 0 35px rgba(255,206,58,0.08);
}


selector .elementor-element-4e8c012:hover
.elementor-element-6182d5c img {

    transform:
        scale(1.025);

    box-shadow:
        0 32px 70px rgba(0,0,0,0.34),
        0 0 35px rgba(255,206,58,0.08);
}


/* =========================================================
   DECORATIVE DOT
========================================================= */

selector .elementor-element-443b89b::before {

    content: "";

    position: absolute;

    width: 8px;
    height: 8px;

    right: -25px;
    top: 20px;

    border-radius: 50%;

    background:
        #FFCE3A;

    box-shadow:
        0 0 0 7px rgba(255,206,58,0.08),
        0 0 25px rgba(255,206,58,0.40);

    opacity: .85;
}


/* =========================================================
   BOTTOM LINE
========================================================= */

selector > .elementor-element-443b89b::after {

    content: "";

    position: absolute;

    bottom: 0;

    left: 8%;

    width: 84%;

    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,206,58,0.25),
            transparent
        );
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1024px) {

    selector {

        padding:
            50px 5% !important;

        border-radius:
            0 0 26px 26px;
    }


    selector .elementor-element-6182d5c {

        max-width:
            410px;
    }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    selector {

        padding:
            45px 20px !important;

        border-radius:
            0 0 22px 22px;
    }


    selector .elementor-element-443b89b {

        text-align:
            center;

        padding:
            0 5px;
    }


    selector .elementor-element-1ca883a {

        margin-bottom:
            18px !important;
    }


    selector .elementor-element-1ca883a p {

        font-size:
            30px !important;

        letter-spacing:
            -.5px;
    }


    selector .elementor-element-1ca883a::after {

        width:
            45px;

        margin:
            12px auto 0;
    }


    selector .elementor-element-b49ccc2 p {

        font-size:
            13.5px !important;

        line-height:
            2 !important;
    }


    selector .elementor-element-4e8c012 {

        margin-top:
            30px;
    }


    selector .elementor-element-6182d5c {

        max-width:
            100%;

        transform:
            rotate(0deg);
    }


    selector .elementor-element-6182d5c img {

        border-radius:
            18px;
    }


    selector .elementor-element-4e8c012:hover
    .elementor-element-6182d5c {

        transform:
            translateY(-5px);
    }


    selector .elementor-element-443b89b::before {

        display:
            none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    selector *,
    selector *::before,
    selector *::after {

        transition:
            none !important;

        animation:
            none !important;
    }
}

/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}

/* =========================================
   RAMIS DIGITAL SHOP - CART PAGE
   Brand: #006660 | Accent: #FFCE3A
========================================= */

/* تنظیمات کلی */
.e-cart__container {
    direction: rtl;
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) 360px;
    gap: 32px;
    align-items: start;
    width: 100%;
}

/* ستون‌ها */
.e-cart__column {
    min-width: 0;
}

/* حذف ظاهر قدیمی جدول */
.woocommerce-cart-form,
.e-cart-section,
.cart-collaterals {
    width: 100%;
}

.woocommerce-cart-form table.cart {
    width: 100%;
    border-collapse: separate !important;
    border-spacing: 0 12px !important;
    border: none !important;
    background: transparent !important;
}

/* هدر جدول */
.woocommerce-cart-form table.cart thead th {
    background: #f5f8f8 !important;
    color: #667070 !important;
    border: none !important;
    padding: 15px 12px !important;
    font-size: 13px !important;
    font-weight: 600 !important;
    text-align: center !important;
    white-space: nowrap;
}

.woocommerce-cart-form table.cart thead th:first-child {
    border-radius: 0 15px 15px 0 !important;
}

.woocommerce-cart-form table.cart thead th:last-child {
    border-radius: 15px 0 0 15px !important;
}

/* کارت هر محصول */
.woocommerce-cart-form table.cart tbody tr.cart_item {
    background: #ffffff !important;
    box-shadow: 0 8px 30px rgba(0, 102, 96, 0.07) !important;
    transition: all 0.25s ease;
}

.woocommerce-cart-form table.cart tbody tr.cart_item:hover {
    box-shadow: 0 12px 35px rgba(0, 102, 96, 0.12) !important;
    transform: translateY(-2px);
}

/* سلول‌ها */
.woocommerce-cart-form table.cart tbody tr.cart_item td {
    padding: 16px 10px !important;
    border: none !important;
    vertical-align: middle !important;
    text-align: center !important;
    color: #253333;
}

.woocommerce-cart-form table.cart tbody tr.cart_item td:first-child {
    border-radius: 0 15px 15px 0 !important;
}

.woocommerce-cart-form table.cart tbody tr.cart_item td:last-child {
    border-radius: 15px 0 0 15px !important;
}

/* عکس محصول */
.woocommerce-cart-form .product-thumbnail {
    width: 100px !important;
}

.woocommerce-cart-form .product-thumbnail a {
    display: block;
    width: 76px;
    height: 76px;
    margin: auto;
    border-radius: 15px;
    overflow: hidden;
    background: #f4f7f7;
}

.woocommerce-cart-form .product-thumbnail img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    display: block;
    border-radius: 15px !important;
}

/* نام محصول */
.woocommerce-cart-form .product-name {
    text-align: right !important;
    min-width: 160px;
}

.woocommerce-cart-form .product-name a {
    color: #182222 !important;
    font-size: 15px !important;
    font-weight: 700 !important;
    line-height: 1.9 !important;
    text-decoration: none !important;
    transition: color 0.2s ease;
}

.woocommerce-cart-form .product-name a:hover {
    color: #006660 !important;
}

/* قیمت‌ها */
.woocommerce-cart-form .product-price,
.woocommerce-cart-form .product-subtotal {
    font-size: 14px !important;
    font-weight: 600 !important;
    white-space: nowrap;
}

.woocommerce-cart-form .product-subtotal {
    color: #006660 !important;
    font-weight: 800 !important;
}

/* دکمه حذف */
.woocommerce-cart-form .product-remove .remove {
    display: flex !important;
    align-items: center;
    justify-content: center;
    width: 34px !important;
    height: 34px !important;
    margin: auto !important;
    border-radius: 10px !important;
    background: #f8eeee !important;
    color: #b84b4b !important;
    font-size: 23px !important;
    font-weight: 400 !important;
    line-height: 1 !important;
    text-decoration: none !important;
    transition: all 0.25s ease;
}

.woocommerce-cart-form .product-remove .remove:hover {
    background: #006660 !important;
    color: #ffffff !important;
    transform: rotate(90deg);
}

/* کنترل تعداد */
.woocommerce-cart-form .quantity {
    display: flex !important;
    justify-content: center;
    align-items: center;
}

.woocommerce-cart-form .quantity .qty {
    width: 64px !important;
    height: 42px !important;
    border: 1px solid #dce5e4 !important;
    border-radius: 10px !important;
    background: #f9fbfb !important;
    color: #006660 !important;
    font-size: 15px !important;
    font-weight: 700 !important;
    text-align: center !important;
    outline: none !important;
    box-shadow: none !important;
}

.woocommerce-cart-form .quantity .qty:focus {
    border-color: #006660 !important;
    background: #ffffff !important;
}

/* مخفی کردن دکمه آپدیت خالی ووکامرس */
.woocommerce-cart-form .actions {
    display: none !important;
}


/* =========================================
   COUPON
========================================= */

.woocommerce-cart-form + .coupon,
.coupon.e-cart-section {
    margin-top: 18px !important;
    padding: 20px !important;
    border: none !important;
    border-radius: 15px !important;
    background: #ffffff !important;
    box-shadow: 0 8px 25px rgba(0, 102, 96, 0.04);
}

.coupon .form-row,
.coupon .coupon-col {
    display: flex !important;
    align-items: center;
    gap: 10px;
    margin: 0 !important;
}

.coupon .coupon-col-start {
    flex: 1;
}

.coupon input.input-text {
    width: 100% !important;
    height: 48px !important;
    padding: 0 16px !important;
    border: 1px solid #dce5e4 !important;
    border-radius: 10px !important;
    background: #fafcfc !important;
    color: #253333 !important;
    font-family: inherit !important;
    outline: none !important;
}

.coupon input.input-text:focus {
    border-color: #006660 !important;
    background: #ffffff !important;
}

.coupon .button,
.coupon button.e-apply-coupon {
    height: 48px !important;
    padding: 0 22px !important;
    border: 1px solid #006660 !important;
    border-radius: 10px !important;
    background: #ffffff !important;
    color: #006660 !important;
    font-family: inherit !important;
    font-weight: 700 !important;
    white-space: nowrap;
    transition: all 0.25s ease;
}

.coupon .button:hover,
.coupon button.e-apply-coupon:hover {
    background: #006660 !important;
    color: #ffffff !important;
}


/* =========================================
   CART TOTALS - کارت مجموع سفارش
========================================= */

.e-cart-totals {
    padding: 0 !important;
}

.cart_totals {
    padding: 28px !important;
    border: none !important;
    border-radius: 15px !important;
    background: #ffffff !important;
    box-shadow: 0 15px 45px rgba(0, 102, 96, 0.09) !important;
}

.cart_totals h2 {
    margin: 0 0 24px !important;
    padding-bottom: 18px !important;
    border-bottom: 1px solid #edf1f1 !important;
    color: #006660 !important;
    font-size: 20px !important;
    font-weight: 800 !important;
}

.cart_totals table {
    width: 100% !important;
    border: none !important;
    margin: 0 !important;
}

.cart_totals table th,
.cart_totals table td {
    padding: 15px 0 !important;
    border: none !important;
    border-bottom: 1px dashed #e2e8e8 !important;
    background: transparent !important;
    color: #536060 !important;
    font-size: 14px !important;
}

.cart_totals table th {
    text-align: right !important;
    font-weight: 500 !important;
}

.cart_totals table td {
    text-align: left !important;
    font-weight: 700 !important;
    color: #253333 !important;
}

/* مجموع نهایی */
.cart_totals .order-total th,
.cart_totals .order-total td {
    padding-top: 22px !important;
    padding-bottom: 20px !important;
    border-bottom: none !important;
    color: #006660 !important;
    font-size: 17px !important;
    font-weight: 800 !important;
}

.cart_totals .order-total strong {
    color: #006660 !important;
    font-size: 18px !important;
}

/* دکمه پرداخت */
.wc-proceed-to-checkout {
    margin: 10px 0 0 !important;
    padding: 0 !important;
}

.wc-proceed-to-checkout .checkout-button {
    display: flex !important;
    align-items: center;
    justify-content: center;
    width: 100% !important;
    min-height: 54px !important;
    margin: 0 !important;
    padding: 12px 20px !important;
    border: none !important;
    border-radius: 12px !important;
    background: #006660 !important;
    color: #ffffff !important;
    font-family: inherit !important;
    font-size: 15px !important;
    font-weight: 700 !important;
    text-decoration: none !important;
    box-shadow: 0 8px 20px rgba(0, 102, 96, 0.18) !important;
    transition: all 0.25s ease;
}

.wc-proceed-to-checkout .checkout-button:hover {
    background: #00524d !important;
    border-color: #00524d !important;
    transform: translateY(-2px);
    box-shadow: 0 12px 25px rgba(0, 102, 96, 0.25) !important;
}


/* =========================================
   RESPONSIVE - TABLET
========================================= */

@media (max-width: 1024px) {
    
    .e-cart__container {
        grid-template-columns: 1fr !important;
        gap: 25px;
    }
}


/* =========================================
   RESPONSIVE - MOBILE
========================================= */

@media (max-width: 767px) {

    .woocommerce-cart-form table.cart,
    .woocommerce-cart-form table.cart tbody {
        display: block !important;
    }

    .woocommerce-cart-form table.cart thead {
        display: none !important;
    }

    .woocommerce-cart-form table.cart tbody tr.cart_item {
        display: grid !important;
        grid-template-columns: 42px 76px 1fr !important;
        gap: 10px;
        padding: 15px !important;
        margin-bottom: 14px !important;
        border: none !important;
        border-radius: 15px !important;
    }

    .woocommerce-cart-form table.cart tbody tr.cart_item td {
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        padding: 7px 0 !important;
        border: none !important;
        border-radius: 0 !important;
        text-align: right !important;
    }

    /* تصویر و نام در ابتدای کارت */
    .woocommerce-cart-form .product-remove {
        grid-column: 1 !important;
        grid-row: 1 !important;
    }

    .woocommerce-cart-form .product-thumbnail {
        grid-column: 2 !important;
        grid-row: 1 !important;
        width: auto !important;
    }

    .woocommerce-cart-form .product-name {
        grid-column: 3 !important;
        grid-row: 1 !important;
        min-width: 0 !important;
    }

    .woocommerce-cart-form .product-price,
    .woocommerce-cart-form .product-quantity,
    .woocommerce-cart-form .product-subtotal {
        grid-column: 1 / -1 !important;
        padding-top: 10px !important;
        border-top: 1px solid #f0f3f3 !important;
    }

    .woocommerce-cart-form table.cart td::before {
        color: #687575 !important;
        font-size: 13px !important;
        font-weight: 500 !important;
    }

    .woocommerce-cart-form .product-thumbnail a {
        width: 70px;
        height: 70px;
    }

    .coupon.e-cart-section {
        padding: 15px !important;
    }

    .coupon .form-row,
    .coupon .coupon-col {
        flex-direction: column !important;
        align-items: stretch !important;
    }

    .coupon .coupon-col-end,
    .coupon button.e-apply-coupon {
        width: 100% !important;
    }

    .cart_totals {
        padding: 22px !important;
        border-radius: 15px !important;
    }
}

